import random
import itertools
import time

n = 21
edges = [(i, j) for i in range(n) for j in range(i+1, n)]
m = len(edges)

# Try a simple random search with local improvements
def count_monochromatic_k5(coloring):
    """Count number of monochromatic K5s"""
    count = 0
    for combo in itertools.combinations(range(n), 5):
        first_color = coloring[edges.index((combo[0], combo[1]))]
        is_mono = True
        for i in range(5):
            for j in range(i+1, 5):
                if i == 0 and j == 1:
                    continue
                idx = edges.index((combo[i], combo[j]))
                if coloring[idx] != first_color:
                    is_mono = False
                    break
            if not is_mono:
                break
        if is_mono:
            count += 1
    return count

